/**
 * Shared `.env` / `.env.local` writers for CLI commands that mint tokens.
 */
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { resolveLinkedFile, restrictExistingPrivateFile, writePrivateFile, } from "./private-file.js";
function isErrnoException(error) {
    return error instanceof Error && "code" in error;
}
async function readOptionalFile(path) {
    try {
        return await readFile(path, "utf8");
    }
    catch (error) {
        if (isErrnoException(error) && error.code === "ENOENT") {
            return "";
        }
        throw error;
    }
}
/**
 * Append `KEY=value` lines to an env file, replacing every existing line
 * for the same key instead of appending duplicates. Creates the file when
 * missing.
 */
export async function upsertEnvFile(path, entries) {
    const target = await resolveLinkedFile(path);
    await restrictExistingPrivateFile(target, { privateDirectory: false });
    const existing = await readOptionalFile(target);
    const lines = existing === "" ? [] : existing.replace(/\r?\n$/, "").split(/\r?\n/);
    // A stale `export KEY=…` line would shadow or duplicate the bare line
    // under some loaders; treat both spellings as the same entry.
    const matchesKey = (line, key) => line.startsWith(`${key}=`) || line.startsWith(`export ${key}=`);
    for (const { key, value } of entries) {
        const next = `${key}=${value}`;
        let replaced = false;
        for (let i = 0; i < lines.length;) {
            if (!matchesKey(lines[i] ?? "", key)) {
                i += 1;
                continue;
            }
            if (replaced) {
                lines.splice(i, 1);
                continue;
            }
            lines[i] = next;
            replaced = true;
            i += 1;
        }
        if (!replaced) {
            lines.push(next);
        }
    }
    await writePrivateFile(target, `${lines.join("\n")}\n`, { privateDirectory: false });
}
export async function ensureGitignoreEntry(dir, entry, covers = (line) => line === entry) {
    const path = join(dir, ".gitignore");
    const existing = await readOptionalFile(path);
    if (existing.split(/\r?\n/).some((line) => covers(line.trim()))) {
        return false;
    }
    const next = existing === "" || existing.endsWith("\n")
        ? `${existing}${entry}\n`
        : `${existing}\n${entry}\n`;
    await writeFile(path, next);
    return true;
}
/**
 * Ensure the agent directory's .gitignore covers .env.local (create or
 * append). A bare `.env` line does not count — that pattern matches only
 * the file literally named .env.
 */
export function ensureEnvLocalGitignored(dir) {
    return ensureGitignoreEntry(dir, ".env.local", (line) => /^\.env(\.local\*?|\.\*|\*)$/.test(line));
}
